/* Four macrosections, with voice-only conversations in the local mockup. */
icons.door='<path fill="#63203f" stroke="none" d="M4 22V4L6 2h12l2 2v18h-4V6H8v16Z M9 7l6 2v13l-6-2Z"/><defs><clipPath id="paper-door"><path d="M4 22V4L6 2h12l2 2v18h-4V6H8v16Z"/><path d="M9 7l6 2v13l-6-2Z"/></clipPath></defs><image href="assets/drive/Voemi_Pulsante_scuro_prugna.png" x="0" y="0" width="24" height="24" opacity=".25" preserveAspectRatio="none" clip-path="url(#paper-door)"/><path d="M13 14v2" stroke="#f7eee3" stroke-width="1.4"/>';
let voiceDraft=null,voicePlaying=null;
function voiceBubble(m,i,preview=false){return `<div class="bubble voice-bubble ${m.mine?'mine':''}"><button class="voice-play" aria-label="${voicePlaying===i?'Pausa':'Riproduci'} nota vocale ${i+1}${preview?' in anteprima':''}" onclick="playVoice(${i},${preview})">${voicePlaying===i?'Ⅱ':'▶'}</button><span class="audio-wave" aria-hidden="true">${[9,17,12,25,18,30,13,22,10,26,15,20].map(h=>`<i style="height:${h}px"></i>`).join('')}</span><span>${formatTime(m.duration||18)}</span><span class="bubble-time">${esc(m.time||'Adesso')} · ${m.mine?'Inviata':m.read?'Ascoltata':'Da ascoltare'}</span></div>`}
function voiceComposer(){return `<div class="voice-composer">${voiceDraft?`<p role="status">${voiceDraft.recording?'Registrazione simulata in corso…':'Nota vocale pronta · '+formatTime(voiceDraft.duration)}</p>${voiceDraft.recording?'':'<button class="secondary" onclick="toast(\'Anteprima simulata · nessun audio reale\')">Riascolta la nota</button>'}<div class="voice-actions"><button class="secondary" onclick="cancelVoice()">Elimina</button><button class="primary" onclick="${voiceDraft.recording?'stopVoice()':'sendVoice()'}">${voiceDraft.recording?'Termina registrazione':'Invia nota vocale'}</button></div>`:`<button class="primary" onclick="recordVoice()">${icon('mic')}Registra una nota vocale</button><button class="secondary" onclick="callAgain()">${icon('phone')}Chiama ${personName()}</button>`}</div>`}
function recordVoice(){voiceDraft={recording:true,started:Date.now(),duration:0};render()}
function stopVoice(){if(!voiceDraft?.recording)return;voiceDraft.duration=Math.max(1,Math.min(120,Math.round((Date.now()-voiceDraft.started)/1000)));voiceDraft.recording=false;render()}
function cancelVoice(){voiceDraft=null;render()}
function sendVoice(){if(!voiceDraft||voiceDraft.recording||!state.matched)return;state.messages.push({type:'audio',duration:voiceDraft.duration,mine:true,read:false,time:'Adesso'});voiceDraft=null;render();later(()=>{state.messages.push({type:'audio',duration:18,mine:false,read:false,time:'Adesso'});if(state.view==='chat')render()},1100)}
function playVoice(i,preview=false){if(preview&&!state.premium){openPremium();return}const m=state.messages[i];if(!m)return;voicePlaying=voicePlaying===i?null:i;if(!preview&&!m.mine)m.read=true;render();if(voicePlaying!==null){toast('Riproduzione simulata · nessun audio reale');later(()=>{voicePlaying=null;if(['chat','chatPreview'].includes(state.view))render()},(m.duration||18)*1000)}}
function callAgain(){if(!state.matched)return;voiceDraft=null;voicePlaying=null;go('found');app.querySelector('h1').textContent='Richiama '+personName();const backButton=app.querySelector('.back');if(backButton)backButton.setAttribute('onclick',"go('chat')");app.querySelector('.flow-actions .text-button')?.remove();const p=document.getElementById('peer-ready'),b=document.getElementById('connect-button');if(p)p.textContent=personName()+' sta ricevendo la chiamata · demo';later(()=>{if(p)p.textContent=personName()+' ha accettato · demo';if(b)b.disabled=false},1200)}
const beforeVoiceGo=go;
go=function(view){if(view!==state.view){voiceDraft=null;voicePlaying=null}beforeVoiceGo(view)};
const beforeVoiceRender=render;
render=function(){
 const rooms=state.view==='rooms';if(rooms)state.view='home';
 beforeVoiceRender();
 if(rooms){state.view='rooms';app.querySelector('.free-talk-card')?.remove();app.querySelector('.topic-section-title')?.remove();app.querySelector('h1').textContent='Di cosa ti va di parlare?';app.querySelector('h1').insertAdjacentHTML('afterend','<p class="rooms-intro">Scegli una stanza. Incontra una persona.</p>');}
 else if(state.view==='home'){app.querySelector('.category-grid')?.remove();app.querySelector('.topic-section-title')?.remove();app.querySelector('h1').innerHTML='Due chiacchiere,<br>una nuova voce.';app.querySelector('.free-talk-card').insertAdjacentHTML('afterend','<button class="primary find-now" onclick="selectCategory(8)">Trova qualcuno con cui parlare</button>');}
 if(state.view==='category'&&state.category!==8){const b=app.querySelector('.back');if(b)b.setAttribute('onclick',"go('rooms')")}
 document.body.dataset.view=state.view;nav();applyMaterials();
};
render();
